#nullable enable
record CallKey(string CallId, string FromTag, string ToTag);
record PendingInvite(string CallId, string FromTag, uint InviteCSeq,
                     long Generation, bool CancelRequested, CallKey? Dialog);
record SipResponse(uint CSeq, string CSeqMethod, string CallId,
                   string FromTag, string? ToTag, string? ViaBranch);

static class SipResponseMatcher
{
    public static bool IsSameInvite(PendingInvite p, SipResponse r) =>
        r.CSeqMethod == "INVITE" && r.CSeq == p.InviteCSeq &&
        r.CallId == p.CallId && r.FromTag == p.FromTag;
}

// CSeqMethod 是從 response 的 CSeq 標頭解析；response 起始列沒有 method。
// 此簡化模型仍未實作完整 SIP transaction/dialog matching。
// Generation 用來避免舊物件 callback 覆蓋新 UI 狀態。
